L={}
L['1']={"temas":[
 T("Dos nombres para cada triángulo",m('triangulo'),FgX('clasificar'),("Clasificar triángulos","Según sus lados, un triángulo es equilátero, isósceles o escaleno; según su ángulo mayor, es acutángulo, rectángulo u obtusángulo. Todo triángulo lleva un nombre de cada clasificación."),"Un triángulo con ángulos de 90°, 45° y 45° es rectángulo isósceles. Algunas combinaciones no existen: un equilátero tiene sus tres ángulos de 60°, así que siempre es acutángulo. Para nombrarlo completo conviene mirar primero el ángulo mayor y después comparar los lados.",["Lados: equilátero, isósceles, escaleno.","Ángulos: acutángulo, rectángulo, obtusángulo.","Un equilátero nunca es rectángulo."])],
 "recuerda":[R("Según sus lados","un triángulo es equilátero, isósceles o escaleno, según cuántos lados iguales tenga.","5, 5 y 5 cm: equilátero"),R("Según su ángulo mayor","un triángulo puede ser acutángulo, rectángulo u obtusángulo.","90°, 60° y 30°: rectángulo"),R("Todo triángulo","tiene dos nombres, uno por sus lados y otro por sus ángulos.","90°, 45° y 45°: rectángulo isósceles"),R("Un triángulo equilátero","tiene sus tres ángulos de 60°, por eso siempre es acutángulo.","Nunca hay un equilátero rectángulo")]}
L['3']={"temas":[
 T("Familias de cuadriláteros",Fg('cuadrilateros'),FgX('cuadrilatero'),("Clasificar cuadriláteros","Los cuadriláteros se clasifican por sus pares de lados paralelos: el trapezoide no tiene ninguno, el trapecio tiene uno y el paralelogramo tiene dos. Dentro de los paralelogramos están el rectángulo, el rombo y el cuadrado."),"El rectángulo tiene cuatro ángulos rectos y el rombo, cuatro lados iguales; el cuadrado tiene las dos cosas, así que es rectángulo y rombo a la vez. Una frase como «todo rombo es un cuadrado» es falsa, porque un rombo puede no tener ángulos rectos; en cambio «todo cuadrado es un rombo» es verdadera.",["0 pares: trapezoide · 1 par: trapecio.","Todo cuadrado es rombo; no al revés."]),
 T("Lo que cumple todo paralelogramo",Fg('paralelogramo'),FgX('paralelogramo'),("Propiedades del paralelogramo","En un paralelogramo los lados opuestos son iguales, los ángulos opuestos son iguales y los ángulos consecutivos suman 180°."),"Con un solo ángulo se conocen los cuatro: si uno mide 55°, el opuesto también mide 55° y los otros dos miden 125° cada uno. Estas propiedades valen para todos los paralelogramos, también para el rectángulo, el rombo y el cuadrado.",["Opuestos: iguales.","Consecutivos: suman 180°."])],
 "recuerda":[R("Los cuadriláteros","se clasifican en trapezoides, trapecios y paralelogramos según sus pares de lados paralelos.","Trapecio: un solo par"),R("El rectángulo, el rombo y el cuadrado","son paralelogramos, y el cuadrado es rectángulo y rombo a la vez.","Todo cuadrado es rombo"),R("En un paralelogramo","los ángulos opuestos son iguales y los consecutivos suman 180°.","55° y 125°"),R("Una frase que empieza con «todo»","es verdadera solo si se cumple siempre, sin excepciones.","Todo rombo es cuadrado: falso")]}
L['4']={"temas":[
 T("Las diagonales",Fg('diagonales'),FgX('diagonales'),("Diagonales","Una diagonal une dos vértices no consecutivos; todo cuadrilátero tiene dos. En los paralelogramos se cortan en su punto medio, y sus propiedades permiten reconocer los especiales."),"En el rectángulo las diagonales son iguales, en el rombo son perpendiculares y en el cuadrado son iguales y perpendiculares. Por eso, para construir un rombo se pueden trazar primero dos segmentos perpendiculares que se corten en su punto medio y después unir sus extremos.",["Rectángulo: iguales · Rombo: perpendiculares.","Cuadrado: las dos cosas."]),
 T("La suma es 360°",Fg('suma360'),FgX('suma360'),("Suma de los ángulos de un cuadrilátero","Los cuatro ángulos interiores de cualquier cuadrilátero suman 360°, porque una diagonal lo divide en dos triángulos y cada uno aporta 180°."),"Si tres ángulos miden 85°, 95° y 100°, el cuarto mide 360° − 280° = 80°. Esto vale para todos los cuadriláteros, también para los que no tienen ningún lado paralelo. Si la resta da cero o negativo, esos ángulos no pueden ser de un cuadrilátero.",["2 triángulos → 360°.","360° − 85° − 95° − 100° = 80°."])],
 "recuerda":[R("Una diagonal","es el segmento que une dos vértices no consecutivos de un polígono.","Todo cuadrilátero tiene 2"),R("En todo paralelogramo","las dos diagonales se cortan en su punto medio.","Diagonal de 18 cm → 9 y 9"),R("Las diagonales del rectángulo son iguales","las del rombo son perpendiculares y las del cuadrado, las dos cosas.","Cuadrado: iguales y perpendiculares"),R("Los ángulos interiores de un cuadrilátero","suman siempre 360°, porque se puede partir en dos triángulos.","85° + 95° + 100° + 80° = 360°")]}
guardar('contenido/matematica-1/mision-18/mision-18.json',L)
